import numpy as np

def transform(grid):
    a=np.array(grid,dtype=int); colors,counts=np.unique(a,return_counts=True)
    # isolated marker color is the least frequent non-background color; background is most common
    bg=colors[np.argmax(counts)]
    candidates=[(int(c),int(n)) for c,n in zip(colors,counts) if c!=bg]
    marker=min(candidates,key=lambda x:x[1])[0]
    coords=np.argwhere(a==marker)
    r0,c0=coords.min(axis=0); mask=(a[r0:coords[:,0].max()+1,c0:coords[:,1].max()+1]==marker)
    out=a.copy()
    variants=[]
    for flip in (False,True):
        m=np.fliplr(mask) if flip else mask
        for k in range(4):
            v=np.rot90(m,k)
            if not any(v.shape==w.shape and np.array_equal(v,w) for w in variants): variants.append(v)
    for m in variants:
        h,w=m.shape
        for r in range(a.shape[0]-h+1):
            for c in range(a.shape[1]-w+1):
                region=a[r:r+h,c:c+w]
                if np.all(region[m]==0): out[r:r+h,c:c+w][m]=marker
    return out.tolist()

